"""Presentation layer for the institutional homepage; no external dependencies."""
import html
from hero_energy import energy_overlay

def e(value):
    return html.escape(str(value), quote=True)

def signal_map():
    return '''<div class="signal-map" aria-label="Integração entre engenharia elétrica, automação e sistemas"><svg viewBox="0 0 1100 150" fill="none" aria-hidden="true"><path class="signal-track" d="M55 75H410Q440 75 440 105T470 135H630Q660 135 660 105T690 75H1045"/><path class="signal-current" d="M55 75H410Q440 75 440 105T470 135H630Q660 135 660 105T690 75H1045"/><circle cx="55" cy="75" r="5"/><circle cx="550" cy="135" r="5"/><circle cx="1045" cy="75" r="5"/></svg><a href="/servicos/engenharia-eletrica/"><span class="signal-symbol" aria-hidden="true">⌁</span><strong>Energia</strong><span>Engenharia e painéis elétricos</span></a><a href="/servicos/automacao/"><span class="signal-symbol" aria-hidden="true">⌘</span><strong>Controle</strong><span>Máquinas e processos</span></a><a href="/servicos/sistemas/"><span class="signal-symbol" aria-hidden="true">↗</span><strong>Informação</strong><span>Sistemas e gestão</span></a></div>'''

def capability_explorer(services):
    content = [
        ('sistemas','Sistemas','Informação que vira decisão.','Uma visão integrada de produção, serviços, estoque e finanças. Sistemas desenvolvidos para a rotina da sua empresa.',['Software sob medida','Gestão e indicadores','Acesso pelo celular'],'/assets/portfolio/sistema-gestao-integrada/01.jpg','Visão do sistema de gestão desenvolvido pela RP Caconde','interface'),
        ('automacao','Automação','Cada movimento, sob controle.','Do sinal do sensor à lógica da máquina. Integramos comandos, acionamentos e interfaces para o seu processo operar.',['CLPs e interfaces','Acionamentos e controle','Integração de máquinas'],'/assets/engenharia-paineis.jpg','Composição institucional ilustrativa de engenharia e automação','photo'),
        ('engenharia-eletrica','Engenharia elétrica','A base de toda a operação.','Projetos e documentação para construir, ampliar ou modernizar instalações, com decisões técnicas orientadas pelo levantamento.',['Projetos executivos','Dimensionamento','Documentação técnica'],'/assets/portfolio/estacao-elevatoria-esgoto/layout-painel.jpg','Layout técnico de um painel projetado pela RP Caconde','document'),
        ('paineis-eletricos','Painéis elétricos','Precisão em cada conexão.','Comando, proteção e distribuição reunidos em uma montagem organizada, identificada e integrada ao equipamento.',['Quadros e CCMs','Comando e proteção','Montagem e integração'],'/assets/detalhe-painel.jpg','Composição institucional ilustrativa de conexões elétricas','photo'),
    ]
    tabs=[];panels=[]
    for i,(slug,name,title,copy,features,src,alt,kind) in enumerate(content):
        tabs.append(f'<button role="tab" id="capability-tab-{slug}" aria-controls="capability-{slug}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-capability="{slug}">{name}<span aria-hidden="true">↗</span></button>')
        panels.append(f'''<div role="tabpanel" class="capability-panel" id="capability-{slug}" aria-labelledby="capability-tab-{slug}" {'hidden' if i else ''}><div class="capability-image is-{kind}"><img src="{src}" alt="{alt}" loading="lazy" decoding="async"><span>{'Interface de um projeto RP Caconde' if kind=='interface' else 'Documento de um projeto RP Caconde' if kind=='document' else 'Imagem conceitual'}</span></div><div class="capability-content"><h3>{title}</h3><p>{copy}</p><ul>{''.join('<li>'+e(x)+'</li>' for x in features)}</ul><a class="text-link" href="/servicos/{slug}/">Conheça a especialidade <span aria-hidden="true">↗</span></a></div></div>''')
    more=''.join(f'<a href="/servicos/{s["slug"]}/"><h3>{e(s["name"])}</h3><p>{e(s["short"])}</p><span aria-hidden="true">↗</span></a>' for s in services[4:])
    return f'''<section class="capabilities section"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Soluções RP Caconde</p><h2>Especialidades que se encontram.<br>Uma operação que evolui.</h2></div><a class="text-link" href="/servicos/">Todas as soluções <span aria-hidden="true">↗</span></a></div><div class="capability-explorer" data-capability-explorer><div class="capability-tabs" role="tablist" aria-label="Explore nossas especialidades">{''.join(tabs)}</div>{''.join(panels)}</div><div class="solution-more">{more}</div></div></section>'''

def render_home(projects, services, mobile_section, faq, card):
    selected=['estacao-elevatoria-esgoto','sistema-gestao-integrada','prensa-retrofit']
    works=''.join(card(next(p for p in projects if p['id']==slug)) for slug in selected)
    questions=[('Posso contratar apenas um serviço?','Sim. O escopo pode abranger uma especialidade ou integrar engenharia elétrica, painéis, automação e sistemas. A proposta define cada entrega.'),('Vocês podem trabalhar com o que já existe na empresa?','Sim. O levantamento identifica o que pode ser aproveitado e as integrações ou atualizações necessárias.'),('Como saber qual solução eu preciso?','Conte o desafio e o cenário atual. A equipe ajuda a definir as informações necessárias para um levantamento e uma proposta.'),('É possível acompanhar a operação pelo celular?','Sim, conforme a arquitetura e os módulos do sistema. O acesso depende das integrações, da conectividade e das permissões definidas no projeto.')]
    return f'''<section class="signature-hero" aria-labelledby="home-title"><div class="signature-art"><div class="signature-scene"><img src="/assets/engenharia-conectada-hero.jpg" width="1774" height="887" alt="Composição conceitual de um painel de automação, motor e conexões de informação" fetchpriority="high" decoding="async">{energy_overlay()}</div></div><div class="signature-shade"></div><div class="wrap signature-content"><p class="hero-specialties">Engenharia elétrica, automação e sistemas</p><h1 id="home-title">Do painel<br>ao seu celular.</h1><p class="signature-lead">Projetamos a infraestrutura.<br>Conectamos os processos.<br>Colocamos a informação nas suas mãos.</p><div class="signature-actions"><a class="button button-primary" href="/servicos/">Explore nossas soluções <span aria-hidden="true">↗</span></a><a class="hero-demo-link" href="/demo/"><span class="play-ring" aria-hidden="true">▷</span>Experimente o sistema</a></div></div><div class="wrap signature-baseline"><a href="#visao" class="signature-scroll"><span aria-hidden="true">↓</span>Conheça a RP Caconde</a><p>Da engenharia à operação.<br>Uma visão completa do seu projeto.</p><button class="hero-motion-control" data-motion-toggle aria-pressed="false" aria-label="Pausar movimento da apresentação"><span aria-hidden="true">Ⅱ</span><span data-motion-label>Pausar movimento</span></button></div></section>
<section class="signature-intro section" id="visao"><div class="wrap"><div class="signature-intro-copy"><div><p class="eyebrow">Pensar o todo. Executar cada detalhe.</p><h2>Seu processo tem desafios.<br>A engenharia conecta as soluções.</h2></div><div><p>Uma máquina precisa de controle. Uma instalação, de engenharia. Uma empresa, de informação.</p><p>A RP Caconde reúne essas especialidades para projetar, executar e integrar o que a sua operação precisa.</p><a class="text-link" href="/empresa/">Conheça a empresa <span aria-hidden="true">↗</span></a></div></div>{signal_map()}</div></section>
{capability_explorer(services)}
{mobile_section()}
<section class="signature-work section wrap"><div class="section-heading"><div><p class="eyebrow">Engenharia em campo</p><h2>O trabalho real<br>por trás de cada conexão.</h2></div><div><p>Projetos, montagem, programação e execução.<br>Conheça o que já desenvolvemos.</p><a class="text-link" href="/portfolio/">Os {len(projects)} trabalhos do portfólio <span aria-hidden="true">↗</span></a></div></div><div class="signature-projects">{works}</div></section>
<section class="signature-method"><div class="signature-method-visual"><img src="/assets/portfolio/secador-cafe/04.jpg" alt="Identificação dos bornes de um painel executado pela RP Caconde" width="1280" height="960" loading="lazy"><span>Montagem real RP Caconde · Secador de café</span></div><div class="signature-method-copy"><p class="eyebrow">Da necessidade à entrega</p><h2>Precisão no projeto.<br>Cuidado na execução.</h2><p>Levantamento, desenvolvimento, testes e orientação. Cada etapa prepara a próxima, com o escopo e as responsabilidades definidos para a sua operação.</p><a class="button button-white" href="/como-trabalhamos/">Conheça nosso processo <span aria-hidden="true">↗</span></a><div class="method-sequence"><span>Entender</span><i aria-hidden="true"></i><span>Desenvolver</span><i aria-hidden="true"></i><span>Entregar</span></div></div></section>
<section class="section wrap signature-faq"><div><p class="eyebrow">Vamos conversar</p><h2>Comece com<br>o seu desafio.</h2><p>Não precisa chegar com a solução pronta.<br>Conte o cenário e o que você quer melhorar.</p><a class="text-link" href="/contato/">Converse com a engenharia <span aria-hidden="true">↗</span></a></div>{faq(questions)}</section>'''
